import{_ as t}from"./chunks/cngal-background-logo.CTvRSuWB.js";import{_ as o,o as e,c as r,a5 as i}from"./chunks/framework.BEZBAInb.js";const g=JSON.parse('{"title":"關於 Konado","description":"","frontmatter":{"title":"關於 Konado","order":1},"headers":[],"relativePath":"tc/latest/introduction/konado.md","filePath":"tc/latest/introduction/konado.md","lastUpdated":1788455378000}'),s={name:"tc/latest/introduction/konado.md"};function n(d,a,l,h,c,p){return e(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="關於-konado" tabindex="-1">關於 Konado <a class="header-anchor" href="#關於-konado" aria-label="Permalink to &quot;關於 Konado&quot;">​</a></h1><h2 id="專案簡介" tabindex="-1">專案簡介 <a class="header-anchor" href="#專案簡介" aria-label="Permalink to &quot;專案簡介&quot;">​</a></h2><p>Konado 是一款基於 Godot Engine 的視覺小說引擎框架，由開源社群驅動。我們致力於為開發者提供高效、便捷的視覺小說開發體驗，幫助創作者快速構建高品質的視覺小說作品，為創作賦能。我們追求更友好、更高效的工具，讓遊戲創作者能夠專注於故事敘述與藝術表現，而不必陷入程式實作的細節之中。</p><h2 id="專案榮譽" tabindex="-1">專案榮譽 <a class="header-anchor" href="#專案榮譽" aria-label="Permalink to &quot;專案榮譽&quot;">​</a></h2><ul><li>Konado 已被收錄至 Godot Engine 官方 <a href="https://github.com/godotengine/awesome-godot" target="_blank" rel="noreferrer">awesome-godot</a> 專案的「Plugins and scripts」部分，作為推薦插件之一。</li><li>Konado 榮幸獲得 <a href="https://atomgit.com/GitCode/G-Star100" target="_blank" rel="noreferrer">2025 AtomGit 百大開源專案</a> 榮譽，並被收錄於 <a href="https://gstar-landscape.gitcode.com/?item=%E9%9F%B3%E8%A7%86%E9%A2%91-%E5%9B%BE%E5%BD%A2-%E6%B8%B8%E6%88%8F-3d--%E6%B8%B8%E6%88%8F%E5%BC%95%E6%93%8E-unity-unreal-godot--konado" target="_blank" rel="noreferrer">AtomGit G-Star Landscape 3.0</a> 生態全景圖中。</li></ul><h2 id="專案貢獻者" tabindex="-1">專案貢獻者 <a class="header-anchor" href="#專案貢獻者" aria-label="Permalink to &quot;專案貢獻者&quot;">​</a></h2><p>以下貢獻者圖表由 <a href="https://contrib.rocks" target="_blank" rel="noreferrer">contrib.rocks</a> 生成，會即時更新專案貢獻者資訊。</p><picture><source media="(prefers-color-scheme: dark)" srcset="https://contrib.rocks/image?repo=godothub/konado&amp;theme=dark"><source media="(prefers-color-scheme: light)" srcset="https://contrib.rocks/image?repo=godothub/konado"><img alt="貢獻者" src="https://contrib.rocks/image?repo=godothub/konado"></picture><h2 id="github-star-history" tabindex="-1">GitHub Star History <a class="header-anchor" href="#github-star-history" aria-label="Permalink to &quot;GitHub Star History&quot;">​</a></h2><picture><source media="(prefers-color-scheme: dark)" srcset="https://api.star-history.com/svg?repos=godothub/konado&amp;type=date&amp;theme=dark&amp;legend=top-left"><source media="(prefers-color-scheme: light)" srcset="https://api.star-history.com/svg?repos=godothub/konado&amp;type=date&amp;legend=top-left"><img alt="Star History 圖表" src="https://api.star-history.com/svg?repos=godothub/konado&amp;type=date&amp;legend=top-left"></picture><h2 id="atomgit-star-history" tabindex="-1">AtomGit Star History <a class="header-anchor" href="#atomgit-star-history" aria-label="Permalink to &quot;AtomGit Star History&quot;">​</a></h2><p><img src="https://atomgit.com/godothub/konado/starcharts.svg?variant=adaptive" alt="AtomGit Star History"></p><h2 id="贊助我們" tabindex="-1">贊助我們 <a class="header-anchor" href="#贊助我們" aria-label="Permalink to &quot;贊助我們&quot;">​</a></h2><p>如果您喜歡 Konado 專案，並希望支持我們的工作，歡迎透過以下方式贊助我們：</p><ul><li><a href="https://afdian.com/item/52230b2860a011f083ef52540025c377" target="_blank" rel="noreferrer">愛發電</a></li></ul><h2 id="聯絡我們" tabindex="-1">聯絡我們 <a class="header-anchor" href="#聯絡我們" aria-label="Permalink to &quot;聯絡我們&quot;">​</a></h2><p>如果您對 Konado 專案感興趣，歡迎加入我們的 QQ 頻道交流群，一同探討 Konado 的未來發展方向：</p><ul><li>QQ 頻道交流群：<a href="https://pd.qq.com/g/godot" target="_blank" rel="noreferrer">https://pd.qq.com/g/godot</a></li></ul><p>如有問題回饋或功能建議，歡迎前往 Konado 的專案<a href="https://github.com/godothub/konado/issues" target="_blank" rel="noreferrer">倉庫提交 Issue</a>。</p><p>如有其他問題，請寄送郵件至：<a href="mailto:konado@godothub.com" target="_blank" rel="noreferrer">konado@godothub.com</a></p><h2 id="致謝" tabindex="-1">致謝 <a class="header-anchor" href="#致謝" aria-label="Permalink to &quot;致謝&quot;">​</a></h2><p><a href="https://www.cngal.org" target="_blank" rel="noreferrer"><img src="'+t+'" alt="CNGAL"></a></p>',22)])])}const b=o(s,[["render",n]]);export{g as __pageData,b as default};
